patch(site/'hub.js',"actions.append(favoriteButton(g));d.append(actions)","actions.append(btn('Chi tiết','secondary',()=>showGameDetail(g)));actions.append(favoriteButton(g));d.append(actions)")
patch(site/'hub.js',"['offline','Offline',g=>!!states[g.id]]];","['offline','Offline',g=>!!states[g.id]],['recent','Gần đây',g=>recent.includes(g.id)],['updates','Cập nhật',g=>!!details[g.id]?.updateAvailable]];")
with (site/'hub.js').open('a') as f:f.write('''
const AMBIENT='xi:ui:ambient-v1',ambient=$('ambientEnabled');ambient.checked=readPref('localStorage',AMBIENT)!=='0';function applyAmbient(){docRoot.dataset.ambient=ambient.checked?'on':'off'}ambient.onchange=()=>{writePref('localStorage',AMBIENT,ambient.checked?'1':'0');applyAmbient()};applyAmbient();
const gameDetail=$('gameDetail');let detailFocus=null;
function showGameDetail(g){if(gameDetail.open)return;if(typeof gameDetail.showModal!=='function'){select('library');return}detailFocus=document.activeElement;const d=details[g.id];$('gameDetailCover').src=g.cover;$('gameDetailTitle').textContent=g.title;$('gameDetailGenre').textContent=g.subtitle+' · '+g.genre;$('gameDetailDescription').textContent=g.description;$('gameDetailStatus').textContent='V'+g.version+' · '+(d?.updateAvailable?'Có bản cập nhật':states[g.id]?'Sẵn sàng offline':workerReady?'Chưa tải offline':'Đang kiểm tra tài nguyên');$('gameDetailActions').replaceChildren(btn('Mở trò chơi','primary',()=>{gameDetail.close();launch(g)},busy||(!states[g.id]&&(!navigator.onLine||!workerReady))),btn('Thư viện game','secondary',()=>{gameDetail.close();select('library')}));gameDetail.showModal();$('gameDetailClose').focus()}
$('gameDetailClose').onclick=()=>gameDetail.close();gameDetail.addEventListener('close',()=>{if(detailFocus?.isConnected&&detailFocus.getClientRects().length)detailFocus.focus({preventScroll:true});detailFocus=null});
''')
with (site/'hub.css').open('a') as f:f.write('''
.game-row .actions>button:not(.favorite-toggle){flex:1 1 108px;min-width:min(108px,100%);overflow-wrap:anywhere}.game-row .actions>.favorite-toggle{flex:0 0 44px;min-width:44px}
/* Final atmosphere: static gradients, no continuous GPU animation. */
html[data-ambient=on][data-glass=on][data-motion=on] body{background:radial-gradient(ellipse at 85% 10%,color-mix(in srgb,var(--gold) 12%,transparent),transparent 42%),radial-gradient(ellipse at 12% 0,var(--glow),transparent 50%),var(--bg)}
#gameDetail{box-sizing:border-box;width:min(480px,calc(100% - 32px));max-height:calc(100dvh - 32px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));overflow:auto;overscroll-behavior:contain;padding:16px;border:1px solid var(--line);border-radius:22px;background:var(--surface);color:var(--ink);box-shadow:0 22px 60px #0006;overflow-wrap:anywhere}#gameDetail::backdrop{background:#0009}#gameDetailCover{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;margin:10px 0}#gameDetail h2{font-size:clamp(22px,5vw,32px);margin:8px 0}#gameDetail p{margin:9px 0;font-size:14px}#gameDetail .detail-top{display:flex;align-items:center;justify-content:space-between;gap:8px}#gameDetail .actions{display:flex;flex-wrap:wrap;gap:8px}#gameDetail .actions button{flex:1 1 120px;min-width:0;min-height:44px;white-space:normal}html[data-glass=on] #gameDetail{background:linear-gradient(140deg,var(--surface-raised),var(--surface));box-shadow:inset 0 1px 0 #fff2,0 22px 60px #0006}html[data-motion=on] #gameDetail[open]{animation:xi-dialog-in 180ms ease-out}@media(prefers-reduced-motion:reduce){#gameDetail{animation:none!important}}
''')
